from dataclasses import dataclass

@dataclass(frozen=True)
class Invoice:
    invoice_id: str
    amount: float

def parse_invoice(record: dict) -> Invoice:
    try:
        amount = float(record['amount'])
    except (KeyError, TypeError, ValueError) as err:
        raise ValueError('amount must be a number') from err
    if amount < 0:
        raise ValueError('amount cannot be negative')
    return Invoice(str(record['invoice_id']), amount)

assert parse_invoice({'invoice_id':1,'amount':'8'}).amount == 8
try:
    parse_invoice({'invoice_id':2,'amount':'oops'})
except ValueError as err:
    print(str(err))
